setSurface('admin');
initializeSettings();
const $ = selector => document.querySelector(selector), content = $('#content');
const state = { user:null, route:'dashboard', epoch:0, order:null, selected:null, orders:null, filters:{}, orderPage:1, userPage:1, ticketPage:1, userQuery:'', ticketStatus:'', ticketType:'', ticketCategory:'', reasons:null, operationBusy:false, settings:null, tickets:[], requestKeys:new Map() };
const titles = () => ({dashboard:L('经营首页','Overview'),orders:L('订单工作台','Orders'),people:L('管理员','Administrators'),support:L('售后与反馈','Support & feedback'),settings:L('设置与维护','Settings'),coupons:L('优惠券','Coupons'),advertisements:L('广告管理','Advertisements')});
const button = (action,label,kind='') => `<button class="button ${kind}" data-action="${action}" type="button">${esc(label)}</button>`;
const empty = (title,body,extra='') => `<section class="empty-state"><span class="empty-mark" aria-hidden="true">◫</span><h2>${esc(title)}</h2><p>${esc(body)}</p>${extra}</section>`;
const badge = value => `<span class="badge ${['financial_exception','print_failed','delivery_failed'].includes(value)?'problem':'attention'}">${esc(status(value))}</span>`;
const field = (name,label,{value='',type='text',required=false,max=500,min,options,textarea=false,checked=false}={}) => type==='checkbox'
  ? `<label class="check-field"><input type="checkbox" name="${name}" ${required?'required':''} ${checked?'checked':''}><span>${esc(label)}</span></label>`
  : `<label class="field"><span>${esc(label)}</span>${options?`<select name="${name}" ${required?'required':''}>${options.map(([v,label])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`).join('')}</select>`:textarea?`<textarea name="${name}" maxlength="${max}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${min===undefined?'':`min="${min}"`} ${type==='number'?`max="${max}" step="1"`:`maxlength="${max}"`} ${type==='password'?'minlength="1" autocomplete="current-password"':''}>`}</label>`;
function notify(message,failed=false){const node=$('#global-status');node.textContent=message;node.className='status '+(failed?'error':'success');}
function chrome(){document.title=L('校园打印 · 经营后台','Campus Print · Operations');$('.brand').firstChild.textContent=L('校园打印 ','Campus Print ');$('#brand-suffix').textContent=L('经营后台','Operations');$('#student-link').textContent=L('学生端入口','Student site');$('#admin-account').textContent=state.user?.nickname||L('管理员登录','Administrator sign in');$('#admin-logout').textContent=L('退出','Sign out');$('#admin-profile').textContent=L('修改昵称','Edit nickname');$('#admin-logout').hidden=$('#admin-profile').hidden=$('#admin-security').hidden=!state.user;$('#admin-security').textContent=L('账号安全','Account security');$('#refresh').textContent=L('刷新','Refresh');$('#page-title').textContent=titles()[state.route];$('#page-eyebrow').textContent=L('本栋宿舍 · A4 黑白','This dormitory · A4 grayscale');$('.admin-nav').setAttribute('aria-label',L('经营导航','Operations navigation'));document.querySelectorAll('[data-view]').forEach(link=>{link.lastElementChild.textContent=({people:L('管理员','Admins'),support:L('售后与反馈','Support')})[link.dataset.view]||titles()[link.dataset.view];if(link.dataset.view===state.route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});}
function modal({title,impact='',fields='',submitLabel=L('确认操作','Confirm'),onSubmit,onConflict}){
  const dialog=document.createElement('dialog');dialog.className='dialog operation-dialog';dialog.setAttribute('aria-label',title);
  dialog.innerHTML=`<form><h2>${esc(title)}</h2>${impact?`<p class="notice">${esc(impact)}</p>`:''}${fields}<p class="status error" role="alert" aria-live="polite"></p><div class="actions"><button type="button" class="button" data-close>${L('返回','Back')}</button><button type="submit" class="button primary" data-submit>${esc(submitLabel)}</button></div></form>`;
  document.body.append(dialog);bindReasonForms(dialog);let busy=false,pendingValues=null,lockedInputs=[];dialog.querySelector('[data-close]').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault();});dialog.onclose=()=>dialog.remove();
  dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const values=pendingValues||new FormData(event.currentTarget),submit=dialog.querySelector('[data-submit]'),alert=dialog.querySelector('[role=alert]');submit.disabled=true;submit.textContent=L('正在处理…','Working…');alert.textContent='';
    try{await onSubmit(values,dialog);dialog.close();}
    catch(error){if(error.code==='NETWORK_ERROR'||error.status>=500){pendingValues ||= values;if(!lockedInputs.length)lockedInputs=[...dialog.querySelectorAll('input,select,textarea')].filter(input=>!input.disabled);lockedInputs.forEach(input=>input.disabled=true);alert.textContent=L('结果尚未确认，请保留原输入重试；不会更换请求幂等键。','The result is uncertain. Retry the original request with the same idempotency key.');}else{pendingValues=null;lockedInputs.forEach(input=>input.disabled=false);lockedInputs=[];if(error.status===409&&onConflict)try{await onConflict();}catch{}alert.textContent=errorMessage(error);}}
    finally{busy=false;submit.disabled=false;submit.textContent=submitLabel;}
  };dialog.showModal();(dialog.querySelector('input,select,textarea')||dialog.querySelector('[data-close]')).focus();return dialog;
}
async function refreshIdentity(){try{const user=await request('/auth/me');state.user=user.role==='admin'?user:null;}catch(error){if(error.status!==401)throw error;state.user=null;}chrome();return state.user;}
function login(){return new Promise((resolve,reject)=>{let done=false;const dialog=modal({title:L('管理员登录','Administrator sign in'),impact:L('使用经营者账号。没有默认密码；请先在服务端初始化管理员。','Use the operator account. There is no default password; initialize an administrator first.'),fields:field('username',L('用户名','Username'),{required:true,max:32})+field('password',L('密码','Password'),{type:'password',required:true,max:128})+button('show-password',L('显示密码','Show password')),submitLabel:L('登录','Sign in'),onSubmit:async form=>{await csrf();state.user=await request('/auth/admin-login',{method:'POST',body:{username:form.get('username'),password:form.get('password')}});done=true;chrome();resolve(state.user);}});
  dialog.querySelector('[data-action=show-password]').onclick=event=>{const input=dialog.querySelector('[name=password]');input.type=input.type==='password'?'text':'password';event.currentTarget.textContent=input.type==='password'?L('显示密码','Show password'):L('隐藏密码','Hide password');};dialog.addEventListener('close',()=>{if(!done)reject(Object.assign(new Error('cancelled'),{code:'USER_CANCELLED'}));});});}
async function ensure(){return await refreshIdentity()||await login();}
async function mutation(route,body){const signature=route+'\n'+JSON.stringify(body);let key=state.requestKeys.get(signature);if(!key){key=crypto.randomUUID();state.requestKeys.set(signature,key);}const result=await request(route,{method:'POST',body,headers:{'Idempotency-Key':key}});state.requestKeys.delete(signature);return result;}
function pageControls(collection,name){return `<div class="pagination"><span>${L('第','Page')} ${collection.page} ${L('页 · 共','·')} ${collection.total} ${L('条','records')}</span><div class="actions"><button class="button" data-page="${name}" data-step="-1" ${collection.page===1?'disabled':''} aria-label="${L('上一页','Previous page')}">‹</button><button class="button" data-page="${name}" data-step="1" ${collection.page*collection.pageSize>=collection.total?'disabled':''} aria-label="${L('下一页','Next page')}">›</button></div></div>`;}
function bindPaging(){document.querySelectorAll('[data-page]').forEach(node=>node.onclick=async()=>{const property={orders:'orderPage',users:'userPage',tickets:'ticketPage'}[node.dataset.page];state[property]+=Number(node.dataset.step);await renderRoute();});}
async function renderRoute(){
  const epoch=++state.epoch;clearPrivateViews();chrome();content.setAttribute('aria-busy','true');notify('');
  if(!state.user){content.innerHTML=empty(L('登录后开始经营','Sign in to manage orders'),L('在这里核对收款、记录打印、确认本栋配送并处理售后。','Review receipts, record printing, confirm dormitory delivery and handle support.'),button('login',L('管理员登录','Administrator sign in'),'primary'));content.querySelector('[data-action=login]').onclick=async()=>{try{await login();await renderRoute();}catch(error){if(error.code!=='USER_CANCELLED')notify(errorMessage(error),true);}};content.setAttribute('aria-busy','false');return;}
  content.innerHTML=empty(L('正在读取经营记录…','Loading records…'),L('请稍候','Please wait'));
  try{if(!state.reasons){const catalog=await request('/admin/reason-catalog');if(epoch!==state.epoch)return;state.reasons=catalog;setReasonCatalog(catalog);}await ({dashboard:renderDashboard,orders:renderOrders,people:renderPeople,support:renderSupport,settings:renderSettings,coupons:renderCouponPage,advertisements:renderAdvertisementPage})[state.route](epoch);}
  catch(error){if(epoch!==state.epoch)return;if(error.status===401){state.user=null;chrome();}content.innerHTML=empty(L('记录暂时无法读取','Records are unavailable'),errorMessage(error),button('retry',L('重试','Retry'),'primary'));content.querySelector('[data-action=retry]').onclick=async()=>{try{await ensure();await renderRoute();}catch(error){if(error.code!=='USER_CANCELLED')notify(errorMessage(error),true);}};notify(errorMessage(error),true);}
  finally{if(epoch===state.epoch)content.setAttribute('aria-busy','false');}
}
async function imageInto(node,route,epoch=state.epoch){const url=await binaryUrl(route);if(epoch!==state.epoch||!node.isConnected){releaseUrl(url);return;}node.src=url;node.hidden=false;}
async function renderDashboard(epoch){
  const [data,settings]=await Promise.all([request('/admin/dashboard'),request('/admin/settings')]);if(epoch!==state.epoch)return;state.settings=settings;
  const metrics=[['pending_acceptance',L('待接单','Awaiting acceptance')],['in_progress',L('制作与配送中','Making & delivering')],['paused',L('暂停待处理','Paused')],['completed',L('已完成','Completed')]];
  const notices=[];
  if(!data.paymentConfigured)notices.push(L('尚未配置收款信息，学生不能提交付款核对。','Payment information is not configured. Students cannot submit payment for review.'));
  if(data.maintenance.enabled)notices.push(L('系统维护已开启：','System maintenance enabled: ')+data.maintenance.message);
  if(data.cleanup.failures.length||data.cleanup.temporaryCleanupFailures.length||data.cleanup.ledgerError||data.cleanup.backupCleanup?.failures.length)notices.push(L('文件清理或期限台账需要处理。','File cleanup or the retention ledger needs attention.'));
  content.innerHTML=`<div class="stack"><section class="panel" data-announcement-editor></section><section class="panel operation-status" id="operation-status"><div><strong data-operation-state>${settings.acceptingOrders?L('营业中','Open'):L('休息中','Resting')}</strong><p class="hint">${L('休息时暂停新上传、报价与下单；已有订单付款、查询、售后及履约继续。','Resting pauses new uploads, quotes and orders. Existing payments, support and fulfillment continue.')}</p></div><button class="button primary" id="toggle-operation" type="button" ${state.operationBusy?'disabled':''}>${settings.acceptingOrders?L('切换为休息','Pause new orders'):L('开始营业','Open for orders')}</button></section><div class="metrics">${metrics.map(([stage,label])=>`<a class="metric" href="#orders&fulfillmentStage=${stage}"><span>${esc(label)}</span><strong>${data.fulfillmentCounts[stage]}</strong><small>${L('查看订单 →','View orders →')}</small></a>`).join('')}</div>${notices.map(text=>`<p class="notice">${esc(text)} <a href="#settings">${L('前往设置','Open settings')}</a></p>`).join('')}<section class="panel stack"><div class="section-heading"><h2>${L('收退款账目','Receipts & refunds')}</h2><span class="hint">${L('历史订单','Orders')} ${data.totalOrders}</span></div><div class="money-strip"><div><span class="muted">${L('已确认收款','Confirmed receipts')}</span><strong>${money(data.confirmedReceivedFen)}</strong></div><div><span class="muted">${L('实际退款','Paid refunds')}</span><strong>${money(data.actualRefundFen)}</strong></div><div><span class="muted">${L('净收款','Net receipts')}</span><strong>${money(data.netReceivedFen)}</strong></div></div><p class="hint">${L('净收款为实收减实际退款，不是利润。','Net receipts are receipts less paid refunds, not profit.')}</p><p class="notice">${L('今日（上海时间）','Today (Shanghai)')} ${esc(data.today.date)} · ${L('收款','Received')} ${money(data.today.confirmedReceivedFen)} · ${L('退款','Refunded')} ${money(data.today.actualRefundFen)} · ${L('净收款','Net')} ${money(data.today.netReceivedFen)}</p></section><section class="panel stack"><h2>${L('文件保留与清理','File retention & cleanup')}</h2><p>${L('实际送达后七天清理文件，订单及收退款记录保留。','Files are cleared seven days after delivery. Orders and financial records remain.')}</p><p class="hint">${L('最近扫描','Last scan')} ${date(data.cleanup.latestRun?.finishedAt)} · ${L('待清理','Pending')} ${data.cleanup.pendingExpired}</p><a href="#settings">${L('查看清理与运行状态 →','View cleanup & runtime →')}</a></section></div>`;
  $('#toggle-operation').onclick=async event=>{
    if(state.operationBusy)return;const control=event.currentTarget,target=!settings.acceptingOrders;state.operationBusy=true;control.disabled=true;
    let problem;
    try{state.settings=await request('/admin/settings',{method:'PATCH',body:{expectedVersion:settings.version,acceptingOrders:target}});}
    catch(error){problem=error;try{state.settings=await request('/admin/settings');}catch{state.settings=null;}}
    finally{state.operationBusy=false;}
    if(epoch!==state.epoch)return;
    if(!state.settings){control.disabled=true;notify(L('营业状态尚无法确认，请刷新页面重读后再操作。','The service state is unknown. Refresh before another action.'),true);return;}
    try{await renderRoute();}catch{}
    if(problem)notify(errorMessage(problem)+L(' 已重读当前营业状态，请核对结果。',' The current state was reloaded. Review the result.'),true);
    else notify(L('营业状态已更新','Service state updated'));
  };
  await mountAnnouncement(content.querySelector('[data-announcement-editor]'),()=>epoch===state.epoch&&!!state.user);
}
function orderFilters(){const values=state.filters;return `<form id="order-filters" class="panel filters"><div class="search-field">${field('q',L('订单号 / 账号 / 昵称','Order number / account / nickname'),{value:values.q||'',max:120})}</div>${field('fulfillmentStage',L('履约进度','Fulfillment progress'),{value:values.fulfillmentStage||'',options:[['',L('全部进度','All stages')],...stageOptions()]})}${field('status',L('付款 / 历史状态','Payment / historical status'),{value:values.status||'',options:[['',L('全部状态','All statuses')],...displayStatuses.map(code=>[code,status(code)])]})}${field('room',L('房间','Room'),{value:values.room||'',max:40})}${field('from',L('创建时间起','Created from'),{value:values.from?isoLocal(values.from):'',type:'datetime-local'})}${field('to',L('创建时间止','Created to'),{value:values.to?isoLocal(values.to):'',type:'datetime-local'})}<button class="button primary" type="submit">${L('查询','Search')}</button>${values.userId?`<div class="filter-secondary notice">${L('已筛选关联账号','Filtered by account')} <button type="button" class="button" id="clear-user-filter">${L('清除筛选','Clear filter')}</button></div>`:''}</form>`;}
function isoLocal(value){const d=new Date(value);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d).replace(' ','T');}
async function renderOrders(epoch){const query=new URLSearchParams({page:String(state.orderPage),pageSize:'20',...state.filters}),data=await request('/admin/orders?'+query);if(epoch!==state.epoch)return;state.orders=data;
  content.innerHTML=`<div class="stack">${orderFilters()}<div class="workspace"><section><div class="order-list">${data.items.length?data.items.map(order=>`<button class="order-card ${order.id===state.selected?'selected':''}" data-order="${order.id}"><span class="order-code">${esc(order.orderNo)}</span>${stageBadge(order)}<div class="card-line"><span>${esc(order.deliveryAddress.room)}</span><strong>${money(order.totals.totalAmountFen)}</strong></div><p class="hint">${esc(order.user.nickname)} · ${order.totals.contentPages} ${L('内容页','content pages')}</p><p class="hint">${date(order.createdAt)}</p></button>`).join(''):empty(L('没有符合条件的订单','No matching orders'),L('调整筛选条件，或等待学生下单。','Change the filters or wait for a student order.'))}</div>${pageControls(data,'orders')}</section><section id="order-detail" class="detail-panel">${empty(L('选择一笔订单','Select an order'),L('核款、打印清单、配送和退款记录在这里展开。','Open an order to review payment, print instructions, delivery and refunds.'))}</section></div></div>`;
  $('#order-filters').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget),next={};for(const key of ['q','status','room','fulfillmentStage'])if(form.get(key).trim())next[key]=form.get(key).trim();for(const key of ['from','to'])if(form.get(key))next[key]=new Date(form.get(key)+':00+08:00').toISOString();if(state.filters.userId)next.userId=state.filters.userId;state.filters=next;state.orderPage=1;state.selected=null;await renderRoute();};
  $('#clear-user-filter')?.addEventListener('click',async()=>{delete state.filters.userId;state.orderPage=1;await renderRoute();});
  document.querySelectorAll('[data-order]').forEach(node=>node.onclick=async()=>{state.selected=node.dataset.order;document.querySelectorAll('[data-order]').forEach(button=>button.classList.toggle('selected',button===node));await loadOrder();});bindPaging();
  if(state.selected)await loadOrder();
}
async function loadOrder(){const id=state.selected;if(!id||!$('#order-detail'))return;const epoch=state.epoch;try{const order=await request('/admin/orders/'+id);if(epoch!==state.epoch||id!==state.selected)return;state.order=order;drawOrder(order);}catch(error){if(epoch===state.epoch&&id===state.selected){if(error.code==='ORDER_HIDDEN_FROM_MERCHANT'){state.selected=null;state.order=null;await renderRoute();notify(L('该订单已由用户直接取消，已返回经营订单列表。','The user directly cancelled this order. Returned to the order list.'));return;}$('#order-detail').innerHTML=empty(L('订单无法读取','Order unavailable'),errorMessage(error));notify(errorMessage(error),true);}}}
const orderButtons = order => orderActions(order,button);
function drawOrder(order){const addr=order.deliveryAddress,receipt=order.payment.receipt;
  $('#order-detail').innerHTML=`<div class="panel stack"><div><div class="detail-head"><div><p class="order-code">${esc(order.orderNo)}</p><p class="hint">${esc(order.user.nickname)} · @${esc(order.user.username)}</p></div>${stageBadge(order)}</div><div class="detail-meta"><span>${L('创建','Created')} ${date(order.createdAt)}</span><span>${L('记录版本','Version')} ${order.version}</span><span>${L('仅配送本栋宿舍','Delivery within this dormitory only')}</span></div></div>${order.allowedActions.includes('view_query_code')?button('query-code',L('查看 / 复制订单查询码','Reveal / copy order code')):''}<p class="hint">${L('原价打印费','Original print fee')} ${money(order.totals.printAmountFen)} · ${L('优惠','Discount')} −${money(order.totals.discountAmountFen??0)} · ${L('配送','Delivery')} ${money(order.totals.deliveryFeeFen)}${order.coupon?' · '+esc(order.coupon.maskedCode):''}</p>${couponExceptionPanel(order)}<div class="money-strip"><div><span class="muted">${L('应付','Total due')}</span><strong>${money(order.totals.totalAmountFen)}</strong></div><div><span class="muted">${L('已确认收款','Confirmed receipt')}</span><strong>${money(receipt?.amountFen||0)}</strong></div><div><span class="muted">${L('实际退款','Paid refunds')}</span><strong>${money(order.actualRefundFen)}</strong></div></div><p class="hint">${order.totals.contentPages} ${L('内容页（含份数）','content pages (including copies)')} · ${order.totals.sheetCount} ${L('张纸','sheets')} · ${L('配送费','Delivery fee')} ${money(0)} · ${L('净收款','Net receipts')} ${money(order.netReceivedFen)}</p><section class="subsection"><h3>${L('确定的打印清单','Confirmed print manifest')}</h3><p class="notice">${L('生产 PDF 已选页且只含一份内容。打印时选择全部生产 PDF 页面，按清单设置份数及单双面，每份和每个文件独立起纸。下载不代表实际打印完成。','Each production PDF contains one copy of the selected pages. Print all production PDF pages using the listed copies and sidedness. Start each file and each copy on a fresh sheet. Downloading does not complete printing.')}</p><div class="stack">${order.items.map(item=>`<article class="item-card"><p class="filename">${esc(item.originalName)}</p><div class="item-spec"><span>A4 · ${L('黑白','Grayscale')}</span><span>${item.copies} ${L('份','copies')}</span><span>${item.duplex?L('双面','Double sided'):L('单面','Single sided')}</span><span>${item.contentPages} ${L('内容页','content pages')} / ${item.sheetCount} ${L('张纸','sheets')}</span><span>${money(item.amountFen)}</span></div><p class="item-page-numbers">${L('原文件已选页','Selected source pages')}: ${esc(pages(item.pageNumbers))}</p>${order.fileAvailability==='available'?`<div class="actions">${button('preview-'+item.itemId,L('查看生产预览','Production preview'))}${button('download-'+item.itemId,L('下载单份生产 PDF','Download one-copy PDF'))}</div>`:`<p class="status muted">${L('文件已过期或已清理，重新打印请上传文件下新单。','Files have expired or been cleared. Upload new files for a new order.')}</p>`}</article>`).join('')}</div></section><section class="subsection"><h3>${L('收款核对与履约','Payment review & fulfillment')}</h3>${fulfillmentSummary(order)}${!order.payment.configured?`<p class="notice">${L('尚未配置收款信息','Payment information has not been configured')} <a href="#settings">${L('前往配置','Configure payment')}</a></p>`:''}<div class="facts"><dl class="fact"><dt>${L('收款状态','Receipt status')}</dt><dd>${esc(status(order.payment.status))}</dd></dl><dl class="fact"><dt>${L('本栋房间','Dormitory / room')}</dt><dd>${esc(addr.buildingLabel)} · ${esc(addr.room)}</dd></dl><dl class="fact"><dt>${L('可选联系方式','Optional contact')}</dt><dd>${esc(addr.contact)||L('未填写','Not provided')}</dd></dl><dl class="fact"><dt>${L('接收说明','Delivery note')}</dt><dd>${receiptDescription(addr)}</dd></dl></div><p class="hint">${L('最近付款声明','Last payment declaration')}: ${date(order.payment.lastSubmittedAt)} · ${L('管理员确认收款','Operator confirmed receipt')}: ${date(order.payment.confirmedAt)}</p>${order.payment.submissions.map(item=>`<div class="reply"><strong>${L('学生付款声明（仍需核对）','Student declaration (review required)')}</strong><p>${esc(item.channel)} · ${esc(item.reference)} · ${esc(item.note)}</p><small>${date(item.createdAt)}</small></div>`).join('')}${receipt?`<div class="reply"><strong>${L('已确认入账','Confirmed receipt')} ${money(receipt.amountFen)}</strong><p>${esc(receipt.channel)} · ${esc(receipt.reference)}</p><small>${date(receipt.confirmedAt)} · ${L('经办','Operator')} ${esc(receipt.confirmedBy)}</small></div>`:''}${order.payment.exceptions.map(item=>`<p class="notice">${L('财务异常','Financial exception')}: ${esc(item.reason)} · ${L('金额','Amount')} ${money(item.amountFen||0)} · ${item.resolvedAt?L('已解除','Resolved'):L('仍锁定生产','Production locked')}</p>`).join('')}${orderButtons(order)}<details class="action-group"><summary>${L('历史打印与配送记录','Historical printing & delivery')}</summary><p>${esc(status(order.production.status))} · ${order.production.completedContentPages}/${order.totals.contentPages} · ${esc(status(order.delivery.status))}</p></details></section><section class="subsection"><h3>${L('取消与退款记录','Cancellation & refunds')}</h3>${compensationPanel(order)}${order.cancellationRequests.map(item=>`<div class="reply"><strong>${esc(cancellationRecordStatus(item.status))}</strong><p>${esc(item.reason)}</p>${item.resolution&&item.resolution!==item.reason?`<p>${esc(item.resolution)}</p>`:''}<small>${date(item.createdAt)}</small></div>`).join('')}${order.refunds.length?order.refunds.map(refund=>`<div class="refund-card"><div class="card-line"><strong>${money(refund.amountFen)}</strong>${badge(refund.status)}</div><p>${esc(refund.reason)}</p><p class="hint">${refund.fulfillmentDecision?L('剩余履约：','Remaining fulfillment: ')+(refund.fulfillmentDecision==='resume'?L('恢复','Resume'):L('停止','Stop')):''} ${refund.payoutReference?esc(refund.payoutReference):''}</p><div class="actions">${refund.status==='requested'?button('refund-approve-'+refund.id,L('批准（尚未实退）','Approve (not paid out)'))+button('refund-reject-'+refund.id,L('拒绝退款','Reject refund')):refund.status==='approved'?button('refund-paid_out-'+refund.id,L('记录实际退回','Record paid refund'),'primary'):''}</div></div>`).join(''):`<p class="muted">${L('暂无退款记录','No refunds')}</p>`}</section><section class="subsection"><h3>${L('完成时间与文件期限','Completion & file expiry')}</h3><p>${L('实际送达','Delivered')} ${date(order.completedAt)}</p><p>${L('文件到期','Files expire')} ${date(order.filesExpireAt)} · ${esc(status(order.fileAvailability))}</p><p class="hint">${L('订单、收退款、配送和文字售后会保留；重印和退款不延长七天期限。下载到设备的副本需经营者自行清理。','Order, financial, delivery and text support records remain. Reprints and refunds never extend expiry. Clear copies downloaded to your device yourself.')}</p></section><section class="subsection"><h3>${L('操作记录','Activity history')}</h3><ol class="history">${order.events.slice(-25).reverse().map(event=>`<li><strong>${esc(eventName(event.type))}</strong>${eventReason(event)?`<p>${esc(eventReason(event))}</p>`:''}${compensationEvent(event)?`<p>${esc(compensationEvent(event))}</p>`:''}<time>${date(event.createdAt)} · ${L('经办','Operator')} ${esc(event.actorId)}</time></li>`).join('')}</ol></section></div>`;
  $('#order-detail').querySelectorAll('[data-action]').forEach(node=>node.onclick=async()=>{const code=node.dataset.action;try{if(code==='query-code'){if(!order.allowedActions.includes('view_query_code'))return;const epoch=state.epoch,value=await request('/admin/orders/'+order.id+'/query-code');if(epoch!==state.epoch||state.order?.id!==order.id||!state.user)return;privateCodes({title:L('订单查询码','Order query code'),help:L('人工核实后私下交给需要协助的用户。持码者只能查看本单明细、付款信息和售后，不能查看文件或直接取消。','Provide privately after manual verification. The code grants access to this order, payment and support, without file access or direct cancellation.'),items:[{label:order.orderNo,code:value.queryCode,length:32}]});}else if(code==='compensation-code'){const epoch=state.epoch;await revealCoupons([order.compensation.couponId],notify,()=>epoch===state.epoch&&state.selected===order.id&&!!state.user);}else if(code.startsWith('preview-'))preview(order.items.find(item=>item.itemId===code.slice(8)));else if(code.startsWith('download-'))await download(order.items.find(item=>item.itemId===code.slice(9)));else if(code.startsWith('operation-'))operation(code.slice(10));else if(code.startsWith('refund-')){const [,action,...parts]=code.split('-');refundOperation(action,parts.join('-'));}}catch(error){notify(errorMessage(error),true);}});
}
async function download(item){const epoch=state.epoch,url=await binaryUrl(`/admin/orders/${state.order.id}/items/${item.itemId}/print-file`);if(epoch!==state.epoch){releaseUrl(url);return;}const link=document.createElement('a');link.href=url;link.download='campus-print-'+item.itemId+'.pdf';link.click();setTimeout(()=>releaseUrl(url),1000);notify(L('生产 PDF 已下载。请按清单设置打印，软件尚未标记完成。','Production PDF downloaded. Follow the manifest; printing has not been marked complete.'));}
function preview(item){const order=state.order,dialog=document.createElement('dialog');dialog.className='dialog preview-dialog';dialog.setAttribute('aria-label',L('生产文件预览','Production preview'));dialog.innerHTML=`<h2>${L('生产文件预览','Production preview')}</h2><p class="filename">${esc(item.originalName)}</p><p class="hint">${L('一份已选内容 · 页码为生产 PDF 页码','One copy of selected content · Production PDF page numbers')}</p><div class="preview-toolbar">${field('page',L('页码','Page'),{type:'number',value:1,min:1,max:item.selectedPageCount})}<span>/ ${item.selectedPageCount}</span>${button('view',L('查看','View'))}${button('close',L('关闭','Close'))}</div><p class="status" role="status"></p><img class="preview" hidden alt="${L('生产 PDF 页面预览','Production PDF page preview')}">`;document.body.append(dialog);let url=null,sequence=0;
  const show=async()=>{const n=Number(dialog.querySelector('input').value);if(!Number.isInteger(n)||n<1||n>item.selectedPageCount)return;const current=++sequence;dialog.querySelector('[role=status]').textContent=L('正在加载…','Loading…');try{const next=await binaryUrl(`/admin/orders/${order.id}/items/${item.itemId}/preview?page=${n}`);if(!dialog.open||current!==sequence){releaseUrl(next);return;}releaseUrl(url);url=next;const image=dialog.querySelector('img');image.src=url;image.hidden=false;dialog.querySelector('[role=status]').textContent='';}catch(error){dialog.querySelector('[role=status]').textContent=errorMessage(error);}};
  dialog.querySelector('[data-action=view]').onclick=show;dialog.querySelector('[data-action=close]').onclick=()=>dialog.close();dialog.onclose=()=>{sequence++;releaseUrl(url);dialog.remove();};dialog.showModal();dialog.querySelector('input').focus();show();
}
function orderModal({title,impact,fields,resource,build,returnToList=false}){
  let version=state.order.version;const id=state.order.id;
  return modal({title,impact:state.order.orderNo+' · '+impact,fields,onSubmit:async form=>{
    const result=await mutation(`/admin/orders/${id}/${resource}`,{expectedVersion:version,...build(form)});
    if(state.selected===id&&state.route==='orders'){if(returnToList){state.selected=null;state.order=null;await renderRoute();notify(L('已退回付款核对，用户可补充后重新提交。','Payment returned for review. The user can update and resubmit.'));return;}state.order=result;await renderRoute();}
    const current=state.order?.id===id?state.order:result;
    notify(current.payment.status==='confirmed'&&current.fulfillment.stage==='paused'?L('已记录收款；订单仍暂停，请逐项处理剩余原因。','Receipt recorded. The order remains paused; resolve each remaining reason.'):current.payment.status==='rejected'&&resource==='payment-review'?L('已退回付款核对，订单保留。','Payment returned for review. The order is retained.'):L('操作已记录','Operation recorded'));
  },onConflict:async()=>{if(state.selected===id){await loadOrder();if(state.order?.id===id)version=state.order.version;}}});
}
function operation(code){if(code==='refund_request')return refundOperation('request');return runOperation(code,{order:state.order,field,orderModal});}
function refundOperation(action,refundId){return runRefund(action,refundId,{order:state.order,field,orderModal});}
async function renderPeople(epoch){
  const users=await request('/admin/users?'+new URLSearchParams({page:String(state.userPage),pageSize:'20',...(state.userQuery?{q:state.userQuery}:{})}));if(epoch!==state.epoch)return;
  content.innerHTML=`<section class="panel stack" data-admin-list><div class="section-heading"><h2>${L('管理员账号','Administrator accounts')}</h2><span class="hint">${users.total} ${L('位管理员','administrators')}</span></div><form id="user-search" class="admin-search">${field('q',L('账号 / 昵称','Account / nickname'),{value:state.userQuery,max:120})}<button class="button" type="submit">${L('搜索管理员','Search administrators')}</button></form><div>${users.items.length?users.items.map(user=>`<article class="user-row"><div class="card-line"><strong>${esc(user.nickname)}</strong><span class="badge">${L('管理员','Administrator')}</span></div><p>@${esc(user.username)} · ${user.online?L('在线','Online'):L('离线','Offline')}</p><p class="hint">${L('注册','Registered')} ${date(user.createdAt)}<br>${L('登录','Last sign in')} ${date(user.lastLoginAt)}<br>${L('活跃','Last active')} ${date(user.lastActiveAt)}</p></article>`).join(''):`<p class="muted">${L('没有符合条件的管理员','No matching administrators')}</p>`}</div>${pageControls(users,'users')}</section>`;
  $('#user-search').onsubmit=async event=>{event.preventDefault();state.userQuery=new FormData(event.currentTarget).get('q').trim();state.userPage=1;await renderRoute();};bindPaging();
}
async function renderSupport(epoch){
  const tickets=await request('/admin/tickets?'+new URLSearchParams({page:String(state.ticketPage),pageSize:'20',...(state.ticketStatus?{status:state.ticketStatus}:{}),...(state.ticketType?{feedbackType:state.ticketType}:{}),...(state.ticketCategory?{category:state.ticketCategory}:{})}));if(epoch!==state.epoch)return;state.tickets=tickets.items;
  content.innerHTML=`<section class="panel stack" data-support-list><div class="section-heading"><h2>${L('售后与反馈','Support & feedback')}</h2><span class="hint">${L('文字回复和关闭工单不会自动退款','Replies and ticket closure do not pay refunds')}</span></div><form id="ticket-filter" class="support-filters">${field('category',L('反馈类别','Category'),{value:state.ticketCategory,options:[['',L('全部类别','All categories')],['order',L('订单售后','Order support')],['general',L('一般反馈','General feedback')]]})}${field('feedbackType',L('反馈类型','Feedback type'),{value:state.ticketType,options:[['',L('全部类型','All types')],...feedbackTypes.map(([key,zh,en])=>[key,L(zh,en)])]})}${field('status',L('处理状态','Ticket status'),{value:state.ticketStatus,options:[['',L('全部状态','All statuses')],...['open','in_progress','resolved'].map(code=>[code,status(code)])]})}<button class="button" type="submit">${L('筛选工单','Filter tickets')}</button></form><div class="stack">${tickets.items.length?tickets.items.map(ticket=>`<article class="ticket-card" data-ticket-id="${esc(ticket.id)}"><div class="section-heading"><h3>${esc(ticket.subject)}</h3>${badge(ticket.status)}</div><p><span class="badge">${ticket.category==='general'?L('一般反馈','General feedback'):L('订单售后','Order support')}</span></p>${ticketMeta(ticket,{admin:true})}<p class="hint">${ticket.orderNo?esc(ticket.orderNo)+' · ':''}${date(ticket.createdAt)}</p>${ticket.updates.map(update=>`<div class="reply"><p>${esc(update.message)}</p><small>${date(update.createdAt)} · ${L('经办 / 提交者','Author')} ${esc(update.authorId)}</small></div>`).join('')}<div class="actions">${ticket.category==='order'&&ticket.orderId?`<a href="#orders&orderId=${esc(ticket.orderId)}">${L('查看关联订单','View order')}</a>`:''}${button('reply-'+ticket.id,L('回复 / 处理','Reply / update'))}</div></article>`).join(''):empty(L('暂无售后或反馈','No support or feedback'),L('订单售后与一般反馈在这里统一处理，文件清理后文字记录仍保留。','Handle order support and general feedback here. Text records remain after file cleanup.'))}</div>${pageControls(tickets,'tickets')}</section>`;
  $('#ticket-filter').onsubmit=async event=>{event.preventDefault();const values=new FormData(event.currentTarget);state.ticketStatus=values.get('status');state.ticketType=values.get('feedbackType');state.ticketCategory=values.get('category');state.ticketPage=1;await renderRoute();};
  content.querySelectorAll('[data-action^=reply-]').forEach(node=>node.onclick=()=>{
    const ticket=state.tickets.find(item=>item.id===node.dataset.action.slice(6));let version=ticket.version;
    modal({title:L('回复 / 处理反馈','Reply / update feedback'),impact:(ticket.orderNo||L('一般反馈','General feedback'))+' · '+L('文字记录保留，关闭不改变收退款和文件期限。','Text records remain. Closure does not change finances or file expiry.'),fields:field('message',L('回复与处理说明','Reply and handling note'),{required:true,max:4000,textarea:true})+field('status',L('处理状态','Ticket status'),{value:ticket.status,options:['open','in_progress','resolved'].map(code=>[code,status(code)])}),onSubmit:async form=>{await mutation('/admin/tickets/'+ticket.id+'/updates',{expectedVersion:version,message:form.get('message'),status:form.get('status')});await renderRoute();notify(L('回复已记录','Reply recorded'));},onConflict:async()=>{version=(await request('/admin/tickets/'+ticket.id)).version;await renderRoute();}});
  });bindPaging();
}
function cleanupSummary(data){const run=data.latestRun;return `<div class="facts"><dl class="fact"><dt>${L('最近扫描','Last scan')}</dt><dd>${date(run?.finishedAt)}</dd></dl><dl class="fact"><dt>${L('待清理 / 待重试','Pending / retries')}</dt><dd>${data.pendingExpired} / ${data.failures.length+data.temporaryCleanupFailures.length+(data.backupCleanup?.failures.length||0)}</dd></dl></div><p class="hint">${L('每五分钟内扫描一次；到期先禁止访问，物理删除失败继续重试。','Scans at least every five minutes. Access is blocked at expiry even when deletion needs retry.')}</p>${data.backupCleanup?.failures.length?`<p class="notice error">${L('文档备份清理失败，请检查私有备份目录权限后重试。','Document backup cleanup failed. Check private backup permissions and retry.')}</p>`:''}${data.ledgerError?`<p class="notice error">${L('期限台账不可用，文件访问已暂停。','Retention ledger unavailable. File access is paused.')}</p>`:''}${data.failures.map(item=>`<p class="notice error">${L('文件清理失败','File cleanup failed')}: ${esc(item.fileId)} · ${esc(item.code)} · ${L('尝试','Attempts')} ${item.purgeAttempts}</p>`).join('')}${data.temporaryCleanupFailures.map(item=>`<p class="notice error">${L('暂存清理待重试','Temporary cleanup needs retry')}: ${esc(item.code)}</p>`).join('')}`;}
async function renderSettings(epoch){
  const [settings,cleanup]=await Promise.all([request('/admin/settings'),request('/admin/files/cleanup-status')]);if(epoch!==state.epoch)return;state.settings=settings;
  content.innerHTML=`<div class="stack settings-modules"><section class="panel stack" data-settings-module="maintenance"><div class="section-heading"><h2>${L('系统维护','System maintenance')}</h2><span class="badge">${settings.maintenance.enabled?L('维护中','Maintenance on'):L('正常运行','Normal operation')}</span></div><p class="hint">${L('系统维护与营业状态分别控制；已有订单仍可查询、核款、履约和售后。','Maintenance and service opening are separate. Existing orders still support queries, review, fulfillment and support.')}</p>${settings.maintenance.message?`<p>${esc(settings.maintenance.message)}</p>`:''}<button class="button" id="toggle-maintenance" type="button">${settings.maintenance.enabled?L('结束系统维护','End maintenance'):L('开启系统维护','Start maintenance')}</button></section><section class="panel stack" id="merchant-payment-settings" data-settings-module="payment"></section><section class="panel stack" data-settings-module="cleanup"><h2>${L('文件清理与运行状态','File cleanup & runtime')}</h2><div id="cleanup-summary">${cleanupSummary(cleanup)}</div><div class="actions"><button class="button" id="cleanup-status">${L('刷新清理状态','Refresh cleanup status')}</button><button class="button" id="cleanup-run">${L('清理已到期文件','Clear expired files')}</button></div><p class="hint">${L('按已有期限清理文件，未到期文件不受影响。','Cleanup uses recorded deadlines and leaves live files intact.')}</p><p class="hint">${L('处理任务','Processing jobs')}: ${cleanup.processing.running} ${L('运行中','running')} / ${cleanup.processing.queued} ${L('排队','queued')} · ${L('临时上传','Temporary uploads')} 24 h</p></section></div>`;
  $('#toggle-maintenance').onclick=()=>{
    const target=!state.settings.maintenance.enabled,version=state.settings.version;
    modal({title:target?L('开启系统维护','Start maintenance'):L('结束系统维护','End maintenance'),impact:L('维护期间暂停新上传、报价与下单。已有订单处理和售后继续。','Maintenance pauses new uploads, quotes and orders. Existing orders and support remain available.'),fields:field('message',L('维护说明','Maintenance message'),{value:state.settings.maintenance.message,max:500,textarea:true})+field('confirm',L('已了解系统维护的实际影响。','I understand the effect of maintenance.'),{type:'checkbox',required:true}),onSubmit:async form=>{try{state.settings=await request('/admin/settings',{method:'PATCH',body:{expectedVersion:version,maintenance:{enabled:target,message:form.get('message')}}});await renderRoute();notify(L('系统维护状态已更新','Maintenance state updated'));}catch(error){try{state.settings=await request('/admin/settings');await renderRoute();}catch{}throw error;}},onConflict:async()=>{await renderRoute();document.querySelector('.operation-dialog')?.close();notify(L('设置已变化，请核对当前状态后再操作。','Settings changed. Review the current state before another action.'),true);}});
  };
  await mountPaymentSettings({host:$('#merchant-payment-settings'),settings,updated:value=>{state.settings=value;},notify,current:()=>epoch===state.epoch&&!!state.user,modal});
  $('#cleanup-status').onclick=async event=>{const control=event.currentTarget;control.disabled=true;try{const latest=await request('/admin/files/cleanup-status');if(epoch!==state.epoch)return;$('#cleanup-summary').innerHTML=cleanupSummary(latest);notify(L('清理状态已刷新','Cleanup status refreshed'));}catch(error){notify(errorMessage(error),true);}finally{control.disabled=false;}};
  $('#cleanup-run').onclick=()=>modal({title:L('清理已到期文件','Clear expired files'),impact:L('按服务器当前时间清理已到期文件；订单、收退款和文字售后保留，未到期文件不受影响。','Clear expired files at current server time. Orders, finances and text support remain; live files are unaffected.'),fields:field('confirm',L('确认按已有期限执行清理。','Run cleanup using the recorded expiry times.'),{type:'checkbox',required:true}),onSubmit:async()=>{const result=await request('/admin/files/cleanup-run',{method:'POST',body:{}});await renderRoute();notify(L('清理完成：','Cleanup complete: ')+result.purged+L(' 个已清理，',' cleared, ')+result.failed+L(' 个待重试',' need retry'));}});
}
async function navigate(){const [route,...params]=location.hash.slice(1).split('&');state.route=Object.hasOwn(titles(),route)?route:'dashboard';const query=new URLSearchParams(params.join('&'));if(state.route==='orders'){state.filters={};for(const name of ['status','userId','fulfillmentStage'])if(query.get(name))state.filters[name]=query.get(name);state.orderPage=1;state.selected=query.get('orderId');}document.querySelectorAll('.preview-dialog').forEach(dialog=>dialog.close());await renderRoute();}
$('#admin-account').onclick=async()=>{try{await login();await renderRoute();}catch(error){if(error.code!=='USER_CANCELLED')notify(errorMessage(error),true);}};
$('#admin-logout').onclick=async()=>{try{await request('/auth/logout',{method:'POST',body:{}});state.user=null;state.reasons=null;setReasonCatalog(null);state.order=null;state.selected=null;state.requestKeys.clear();clearPrivateViews();await renderRoute();notify(L('已退出登录，私有预览已释放','Signed out. Private previews released.'));}catch(error){notify(errorMessage(error),true);}};
$('#admin-security').onclick=()=>openAccountSecurity(state.user);
$('#admin-profile').onclick=()=>modal({title:L('修改账号昵称','Edit nickname'),fields:field('nickname',L('昵称','Nickname'),{value:state.user.nickname,required:true,max:80}),onSubmit:async form=>{state.user=await request('/me/profile',{method:'PATCH',body:{nickname:form.get('nickname')}});chrome();notify(L('昵称已保存','Nickname saved'));}});
$('#refresh').onclick=async()=>{try{await ensure();await renderRoute();}catch(error){if(error.code!=='USER_CANCELLED')notify(errorMessage(error),true);}};
window.addEventListener('hashchange',navigate);window.addEventListener('cp:language',()=>{chrome();renderRoute();});
window.addEventListener('cp:clear-private-views',()=>{document.querySelectorAll('img[src^="blob:"]').forEach(image=>{image.removeAttribute('src');image.hidden=true;});});
window.addEventListener('cp:file-expired',()=>{document.querySelectorAll('.preview-dialog').forEach(dialog=>dialog.close());if(state.route==='orders'&&state.user)loadOrder();});
window.addEventListener('cp:auth-expired',event=>{if(event.detail?.surface&&event.detail.surface!=='admin')return;state.user=null;state.reasons=null;setReasonCatalog(null);state.order=null;state.selected=null;state.requestKeys.clear();document.querySelectorAll('dialog').forEach(dialog=>dialog.close());renderRoute();notify(L('登录已过期，请重新登录','Your session ended. Sign in again.'),true);});
window.addEventListener('pagehide',()=>{state.epoch++;document.querySelectorAll('.preview-dialog').forEach(dialog=>dialog.close());clearPrivateViews();});
try{await refreshIdentity();await navigate();}catch(error){notify(errorMessage(error),true);content.innerHTML=empty(L('连接暂不可用','Connection unavailable'),errorMessage(error));content.setAttribute('aria-busy','false');}

async function renderCouponPage(epoch){return renderCoupons({content,state,epoch,modal,mutation,notify,refresh:renderRoute});}

async function renderAdvertisementPage(epoch){if(epoch!==state.epoch)return;content.innerHTML=empty(L('此功能暂不可用','This feature is currently unavailable'),L('请使用经营导航继续处理订单。','Use the operations navigation to continue managing orders.'));}
